#include <array>
#include <cstddef>
#include <memory>
#include <utility>

struct Payload {
    std::array<std::byte, 4096> bytes;
};

// Every by-value capture is a data member, so this closure IS the payload:
// the queue copies 4 KiB on every rebalance.
auto make_naive(Payload payload) {
    return [payload] { return payload.bytes[0]; };
}

// The closure owns the payload just as firmly, but stores one pointer to it.
// Cost: one indirection per call, and the closure is now move-only, so the
// queue must accept move-only callables (std::move_only_function, not
// std::function).
auto make_compact(std::unique_ptr<Payload> payload) {
    return [payload = std::move(payload)] { return payload->bytes[0]; };
}

// Copyable variant when the queue insists on copyable targets: the copy is a
// refcount bump, not 4 KiB.
auto make_shared_compact(std::shared_ptr<Payload> payload) {
    return [payload = std::move(payload)] { return payload->bytes[0]; };
}

static_assert(sizeof(decltype(make_naive(Payload{}))) >= sizeof(Payload));
static_assert(sizeof(decltype(make_compact(nullptr))) <= sizeof(void*));
static_assert(sizeof(decltype(make_shared_compact(nullptr)))
              <= 2 * sizeof(void*));

#include <array>
#include <cstddef>

struct Machine {
    int accumulator = 0;
};

using Instruction = void (*)(Machine&, int);

// Captureless lambdas convert to plain function pointers, and that conversion
// is usable in a constant expression - so the whole table is built at compile
// time and lives in read-only data. Unary + forces the conversion so the
// array's element type is deduced from the pointer, not from a closure type.
constexpr std::array<Instruction, 3> instructions{
    +[](Machine& machine, int operand) { machine.accumulator += operand; },
    +[](Machine& machine, int operand) { machine.accumulator *= operand; },
    +[](Machine& machine, int) { machine.accumulator = 0; },
};

void step(Machine& machine, std::size_t opcode, int operand) {
    instructions[opcode](machine, operand);
}

// A C callback slot has room for a pointer to code and a pointer to data, and
// nothing else. A capturing lambda has state to store and therefore no
// conversion; the captureless trampoline below carries its state through the
// slot the API already provides.
extern "C" void register_sink(void (*sink)(void*, int), void* user_data);

void install(Machine& machine) {
    register_sink(
        [](void* user_data, int value) {
            static_cast<Machine*>(user_data)->accumulator += value;
        },
        &machine);
}

#include <cstddef>
#include <functional>
#include <string>
#include <utility>
#include <vector>

struct Record {
    int id;
};

std::size_t flush(const std::vector<Record>& records, std::size_t prefix_length);

std::function<std::size_t()> make_flusher(std::vector<Record> batch,
                                          const std::string& venue) {
    return [records = std::move(batch),          // allocation transfers in
            prefix_length = venue.size()] {      // stores 8 bytes, not the string
        return flush(records, prefix_length);
    };
}

std::function<std::size_t()> broken_flusher(std::vector<Record> batch,
                                            const std::string& venue) {
    // Both captures are borrows of objects that die when this function
    // returns: batch is a by-value parameter and venue is bound to whatever
    // the caller passed. Invoking the callback later is undefined behaviour.
    return [&batch, &venue] { return flush(batch, venue.size()); };
}

std::function<std::size_t()> use() {
    std::vector<Record> batch{{1}, {2}, {3}};
    auto flusher = make_flusher(std::move(batch), "EUREX-PRIMARY");
    // batch is valid but unspecified here: it may be assigned to, queried or
    // destroyed, and nothing else should be assumed about it.
    return flusher;
}

#include <functional>
#include <memory>

class Timer {
public:
    void after(int millis, std::function<void()> callback);
};

class Reconciler : public std::enable_shared_from_this<Reconciler> {
public:
    // Precondition: the reconciler outlives every callback the timer will run.
    // Cost: one pointer in the closure. Failure mode: silent use-after-free
    // inside the timer thread, with no diagnostic anywhere near this line.
    void schedule_borrowed(Timer& timer) {
        timer.after(10, [this] { sweep(pending_); });
    }

    // Precondition: none - the callback is independent of the original.
    // Cost: a full copy of the reconciler in every scheduled callback.
    // Failure mode: not a crash but a stale answer, because updates made after
    // scheduling are invisible to the snapshot.
    void schedule_snapshot(Timer& timer) {
        timer.after(10, [*this] { sweep(pending_); });
    }

    // Precondition: the reconciler is owned by a shared_ptr.
    // Cost: a weak handle plus a lock() per invocation.
    // Failure mode: the work is skipped rather than performed, so this is only
    // correct when cancellation is an acceptable outcome.
    void schedule_guarded(Timer& timer) {
        timer.after(10, [weak = weak_from_this()] {
            if (auto self = weak.lock()) {
                self->sweep(self->pending_);
            }
        });
    }

private:
    void sweep(int pending) const;
    int pending_ = 0;
};

#include <algorithm>
#include <cstddef>
#include <functional>
#include <vector>

std::vector<int> sequence_by_reference(std::size_t count) {
    std::vector<int> values(count);

    // std::generate(values.begin(), values.end(),
    //               [next = 0]() mutable { return ++next; });
    // Unreliable: each copy of the closure carries its own next member, so
    // the accumulated state may end up in a copy the algorithm discards.

    // The state lives outside the closure, so every copy of the closure
    // updates the same object. Obligation: next must outlive the call -
    // trivially true here, and not at all trivial if the closure were stored.
    int next = 0;
    std::generate(values.begin(), values.end(), [&next] { return ++next; });

    return values;
}

struct Counter {
    int next = 0;
    int operator()() { return ++next; }
};

std::vector<int> sequence_by_ref_wrapper(std::size_t count, Counter& counter) {
    std::vector<int> values(count);

    // std::ref hands the algorithm a reference_wrapper: copying that copies
    // the handle, not the counter, so identity survives. Obligation: the
    // caller's Counter must outlive the algorithm call.
    std::generate(values.begin(), values.end(), std::ref(counter));

    // counter.next now reports how many values were produced.
    return values;
}

#include <cstddef>
#include <functional>
#include <span>
#include <utility>
#include <vector>

struct Tick {
    int price;
};

// Inner loop. The concrete closure type is preserved, so the call usually
// inlines and constants propagate into the loop. Owns nothing; the caller
// keeps the callable alive for the duration of the call. Cost: one emitted
// specialization per callable type, and the definition must be in the header.
template<class Handler>
void for_each_tick(std::span<const Tick> ticks, Handler&& handler) {
    for (const Tick& tick : ticks) {
        handler(tick);
    }
}

// Non-owning view: erases the call operation only. Two pointers, no
// allocation, an indirect call the optimizer normally cannot see through.
// Lifetime obligation: the referenced callable must outlive every call made
// through the view - the same discipline a std::string_view demands.
class TickRef {
public:
    template<class F>
    TickRef(F& callable) noexcept
        : object_(&callable),
          invoke_([](void* object, const Tick& tick) {
              (*static_cast<F*>(object))(tick);
          }) {}

    void operator()(const Tick& tick) const { invoke_(object_, tick); }

private:
    void* object_;
    void (*invoke_)(void*, const Tick&);
};

// Boundary: one non-template implementation, compiled once, header free of
// template definitions.
void replay(std::span<const Tick> ticks, TickRef handler);

// Registry: owns a copy of each handler, so the callables may be temporaries
// at the call site. Cost: an erased indirect call plus an allocation whenever
// a target misses the implementation's small-buffer criteria - acceptable on
// a configuration path, not in the loop above.
class Registry {
public:
    void add(std::function<void(const Tick&)> handler) {
        handlers_.push_back(std::move(handler));
    }

    void broadcast(const Tick& tick) const {
        for (const auto& handler : handlers_) {
            handler(tick);
        }
    }

private:
    std::vector<std::function<void(const Tick&)>> handlers_;
};
